(() => {
  const seedList = (window.__scan && window.__scan.brand.list) || [];
  const chars = {};
  for (const b of seedList) { const s = String(b.name || ''); for (const ch of s) { if (/[\u4e00-\u9fa5]/.test(ch)) chars[ch] = (chars[ch] || 0) + 1; } }
  const cjk = Object.keys(chars).sort((a, b) => chars[b] - chars[a]).slice(0, 400);
  const alnum = 'abcdefghijklmnopqrstuvwxyz0123456789'.split('');
  const singles = alnum.slice();
  const bigrams = [];
  for (const a of alnum) for (const b of alnum) bigrams.push(a + b);
  const seeds = bigrams.concat(singles).concat(cjk);
  window.__big = {
    done: false, seeds: seeds, idx: 0, reqs: 0, throttled: 0, errs: 0,
    map: {}, stats: [], maxVid: 407950, started: Date.now(),
    cjkCount: cjk.length, bigramCount: bigrams.length
  };
  for (const b of seedList) window.__big.map[b.vid] = b.name;
  const S = window.__big;
  (async () => {
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    const post = async (seed, page) => {
      for (let a = 0; a < 5; a++) {
        try {
          const r = await fetch('/draco-ms/mms/template/property/value/search', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ cat_id: 5908, pid: 5, template_pid: 642609, page_num: page, page_size: 1000, value: seed }) });
          const j = await r.json();
          if (j && j.success) return Array.isArray(j.result) ? j.result : [];
          if (j && j.error_code === 55555) { S.throttled++; await sleep(2000 * (a + 1)); continue; }
          return null;
        } catch (e) { await sleep(1200 * (a + 1)); }
      }
      return null;
    };
    const worker = async () => {
      while (true) {
        const i = S.idx++;
        if (i >= S.seeds.length) return;
        const seed = S.seeds[i];
        let got = 0, pages = 0, capped = false;
        for (let p = 1; p <= 5; p++) {
          const arr = await post(seed, p);
          pages++;
          if (arr === null) { S.errs++; break; }
          if (!arr.length) break;
          for (const x of arr) { if (!(x.vid in S.map)) S.map[x.vid] = x.value; if (x.vid > S.maxVid) S.maxVid = x.vid; }
          got += arr.length;
          if (arr.length < 1000) break;
          if (p === 5) capped = true;
          await sleep(220);
        }
        S.reqs += pages;
        S.stats.push({ seed: seed, n: got, pages: pages, capped: capped });
        await sleep(240);
      }
    };
    await Promise.all([worker(), worker()]);
    S.done = true; S.finishedAt = Date.now();
  })();
  return JSON.stringify({ msg: 'multi-seed brand scan started', seeds: seeds.length, bigrams: bigrams.length, singles: singles.length, cjk: cjk.length, seed: Object.keys(S.map).length });
})()
